"""Build a self-contained Colab notebook, preserving the original 11-step layout."""
import ast
import json
from pathlib import Path
ROOT = Path(__file__).resolve().parent
NOTEBOOK = ROOT.parent / 'google_colab' / 'NCKH_PhoBERT_RGCN_Training.ipynb'
LOCAL_MODULES = {'labels', 'data_pipeline', 'context_encoder', 'model_gnn', 'training', 'document_io', 'prediction_view', 'reporting'}

class InlineImports(ast.NodeTransformer):

    def visit_ImportFrom(self, node):
        return None if node.module in LOCAL_MODULES else node

    def visit_If(self, node):
        if isinstance(node.test, ast.Compare) and isinstance(node.test.left, ast.Name) and (node.test.left.id == '__name__'):
            return None
        return self.generic_visit(node)

def inline(name, classes=None):
    tree = ast.parse((ROOT / name).read_text(encoding='utf-8-sig'))
    if classes:
        tree.body = [node for node in tree.body if isinstance(node, ast.ClassDef) and node.name in classes]
    tree = InlineImports().visit(tree)
    return ast.unparse(ast.fix_missing_locations(tree)) + '\n'
