code("from pathlib import Path\n\nTRAIN_NEW_MODEL = True  # False: chỉ nạp checkpoint đã train để kiểm tra DOCX\nTRAIN_SEED = 42\n\nDATASET_DIR = Path('/content/drive/MyDrive/NCKH_train/Dataset')\nOUTPUT_DIR = Path('/content/drive/MyDrive/NCKH_Results/phobert_rgcn_v2_run_42')\n# Nếu chạy local, đổi 2 đường dẫn phía trên theo máy của bạn.\n\ndef check_dataset_path(path):\n    path = Path(path)\n    if not path.is_dir():\n        raise FileNotFoundError(f'Không tìm thấy dataset: {path}. Kiểm tra kết nối Drive và tên thư mục ở Bước 3.')\n    files = sorted(path.rglob('*_ket_qua.json'))\n    if not files:\n        names = ', '.join(p.name for p in list(path.iterdir())[:15]) or '(thư mục trống)'\n        raise FileNotFoundError(f'Không có *_ket_qua.json trong {path}. Hãy giải nén dữ liệu nếu còn dạng ZIP. Nội dung thư mục: {names}')\n    return files\n\nif TRAIN_NEW_MODEL and (OUTPUT_DIR/'run_config.json').exists():\n    raise ValueError('OUTPUT_DIR already contains a run. Use a new directory, or set TRAIN_NEW_MODEL=False to test DOCX.')\ndataset_files = check_dataset_path(DATASET_DIR) if TRAIN_NEW_MODEL else []\nOUTPUT_DIR.mkdir(parents=True, exist_ok=True)\ncsv_files = sorted(DATASET_DIR.rglob('*_ket_qua.csv')) if TRAIN_NEW_MODEL else []\nprint(f'✅ Dataset: {DATASET_DIR} — {len(dataset_files)} file JSON, {len(csv_files)} file CSV')\nprint('Huấn luyện đọc JSON (có full_text và nhãn). CSV cùng tài liệu không được nạp lần hai.')\nprint(f'📁 Kết quả: {OUTPUT_DIR}')\n", 'paths')
