code(inline('data_pipeline.py') + '\n' + inline('context_encoder.py') + '\n# AUDIT DATASET\nimport pandas as pd\nfrom IPython.display import display\n\nif globals().get(\'TRAIN_NEW_MODEL\', True):\n    if (OUTPUT_DIR/\'run_config.json\').exists():\n        raise ValueError(\'OUTPUT_DIR already contains a run; choose a new directory before auditing/training.\')\n    documents, audit = load_documents(DATASET_DIR)\n    save_json(OUTPUT_DIR/\'data_audit.json\', audit)\n    display(pd.DataFrame.from_dict(audit[\'totals\'], orient=\'index\', columns=[\'Số lượng\']))\n    display(pd.DataFrame({\'Số quan hệ\': audit[\'relation_counts\'], \'Số văn bản\': audit[\'relation_document_support\']}))\n    supported = sum(n > 0 for n in audit[\'relation_counts\'].values())\n    print(f\'✅ Đã đọc {len(documents)} văn bản. Trần Macro-F1 cố định 22 lớp theo hỗ trợ nhãn: {supported/22:.2%}.\')\n    preview_splits = split_documents(documents, OUTPUT_DIR/\'split_manifest.json\', seed=globals().get("TRAIN_SEED",42))\n    display(pd.DataFrame([{\'Tập\':k,\'Số văn bản\':len(v),\'Số loại quan hệ có mẫu\':len({r[\'code\'] for d in v for r in d[\'relations\']})} for k,v in preview_splits.items()]))\n    print(\'Kiểm tra bảng nhãn hiếm trước khi train. Split nhóm bản trùng chính xác; cần rà soát thêm bản gần trùng và chất lượng nhãn.\')\nelse:\n    print(\'Đã nạp định nghĩa. Chế độ kiểm tra: giữ nguyên dữ liệu và checkpoint đã lưu.\')\n', 'pipeline')
