code(inline('document_io.py') + '\n' + inline('prediction_view.py') + '\n# Chọn một file DOCX mới. Trên Colab, để None để hiện nút tải tệp từ máy.\nINPUT_FILE = None  # Hoặc \'/content/drive/MyDrive/van_ban_moi.docx\'\nPREDICT_VARIANT = \'rgcn\'\n\nfrom datetime import datetime\nfrom IPython.display import HTML, display\n\nif INPUT_FILE is None:\n    if IS_COLAB:\n        from google.colab import files\n        uploaded = files.upload()\n        if len(uploaded) != 1:\n            raise ValueError(\'Hãy chọn đúng một file .docx hoặc .txt để kiểm tra.\')\n        INPUT_FILE = next(iter(uploaded))\n    else:\n        raise ValueError(\'Đặt INPUT_FILE thành đường dẫn DOCX/TXT trên máy.\')\n\nif not (OUTPUT_DIR/\'checkpoints\'/f\'relation_{PREDICT_VARIANT}.pt\').is_file():\n    raise RuntimeError(\'Chưa có checkpoint. Chạy train hoặc chọn OUTPUT_DIR của lần chạy v2 đã hoàn tất.\')\nextractor = Extractor(OUTPUT_DIR, variant=PREDICT_VARIANT, local_files_only=LOCAL_FILES_ONLY)\nprediction, source_info = extractor.predict_file(INPUT_FILE)\nprediction_dir = OUTPUT_DIR/\'predictions\'/(Path(INPUT_FILE).stem+\'_\'+datetime.now().strftime(\'%Y%m%d_%H%M%S\'))\nhtml_path = export_prediction(prediction, prediction_dir, source_info)\nprint(source_info[\'evaluation_note\'])\nprint(f"Nhận diện: {len(prediction[\'entities\'])} thực thể; {len(prediction[\'relations\'])} quan hệ dự đoán.")\nprint(\'Thời gian suy luận (không gồm đọc DOCX/nạp model/vẽ):\', round(prediction[\'inference\'][\'elapsed_seconds\'],2), \'giây\')\nprint(\'Đầy đủ JSON/CSV, văn bản đã đọc, đồ thị PNG và HTML:\', prediction_dir)\ndisplay(pd.read_csv(prediction_dir/\'entities.csv\').head(20))\ndisplay(pd.read_csv(prediction_dir/\'relations.csv\').head(20))\nif IS_COLAB:\n    # Trusted, generated local HTML; iframe keeps scripts separate from notebook UI.\n    import html as html_module\n    display(HTML(\'<iframe style="width:100%;height:1150px;border:1px solid #ddd" sandbox="allow-scripts allow-downloads" srcdoc="\'+html_module.escape(html_path.read_text(encoding=\'utf-8\'),quote=True)+\'"></iframe>\'))\nelse:\n    display(HTML(\'<p>Mở tệp HTML bằng trình duyệt: \'+str(html_path)+\'</p>\'))\n', 'inference')
